// Verifica dell'accessibilità: testi alternativi, contrasto, ordine di lettura, testo che non entra, testi piccoli, campi.
const pgOverlap=(a,b)=>a.x<b.x+b.w&&b.x<a.x+a.w&&a.y<b.y+b.h&&b.y<a.y+a.h,pgCovers=(a,b)=>a.x<=b.x&&a.y<=b.y&&a.x+a.w>=b.x+b.w&&a.y+a.h>=b.y+b.h;
function pgBehind(it,stack){if(it.fill&&it.fill!=='none'&&it.opacity===100)return{color:it.fill};for(let i=stack.indexOf(it)-1;i>=0;i--){const o=stack[i];if(o.hidden||o.kind==='line'||(o.kind==='text'&&o.fill==='none'))continue;if(!pgOverlap(o,it))continue;if(o.kind==='image'&&(o.img||o.field))return{image:o};if(o.fill!=='none'&&o.opacity===100&&pgCovers(o,it))return{color:o.fill,by:o};if(o.fill!=='none')return{partial:o}}return Pg.p.bg==='none'?{none:true}:{color:Pg.p.bg}}
function pgIssues(){const p=Pg.p,out=[],mm=p.unit==='mm',big=mm?24:p.w/36,bigBold=mm?18.66:p.w/48,small=mm?12:p.w/60,fields=new Set((p.data?.fields||[]).map(f=>f.toLowerCase())),insts=pgViewInstances(p),lay=pgLayout(p,insts),overSeen=new Set();
 const where=h=>h.master!==undefined?`pagina ${p.pages.indexOf(h)+1}`:h.name;
 for(const h of [...p.pages,...p.masters]){const isPg=p.pages.includes(h),ii=isPg?insts.findIndex(I=>I.pg===h):-1,m=isPg?pgMasterOf(h):null,stack=[...(m?.items||[]),...h.items],at={pi:isPg?p.pages.indexOf(h):-1,mid:isPg?'':h.id};
  if(isPg&&!mm&&!h.alt.trim()&&h.items.length)out.push({...at,msg:`Pagina ${at.pi+1}: manca la descrizione della pagina, il testo alternativo da usare quando pubblichi il PNG.`,fix:'alt'});
  if(isPg&&!h.readOk){const auto=pgAutoOrder(h).filter(x=>!x.deco).map(x=>x.id),cur=pgReadOrder(h).filter(x=>!x.deco).map(x=>x.id);if(auto.join()!==cur.join())out.push({...at,msg:`Pagina ${at.pi+1}: l’ordine di lettura non segue la disposizione delle cornici (dall’alto in basso, da sinistra a destra). Controllalo nell’elenco delle cornici, oppure usa l’ordine automatico.`,fix:'order'})}
  for(const it of h.items){const A={...at,id:it.id},nm=`«${it.name}» (${where(h)})`;
   if(it.x>=p.w||it.y>=p.h||it.x+it.w<=0||it.y+it.h<=0)out.push({...A,msg:`${nm} è fuori dalla pagina: non verrà stampata.`});
   if(it.kind==='image'&&it.field&&p.data){const i=p.data.fields.indexOf(it.field),miss=p.data.rows.map(r=>String(r[i]??'').trim()).filter(v=>v&&!pgFolderFile(v));if(i<0)out.push({...A,msg:`${nm}: il campo «${it.field}» non c’è più nei dati.`});else if(miss.length)out.push({...A,msg:`${nm}: ${miss.length===1?'un’immagine indicata dai dati non si trova':miss.length+' immagini indicate dai dati non si trovano'} nella cartella collegata (${[...new Set(miss)].slice(0,5).join(', ')}).`})}
   if(it.kind==='image'){if(!it.img&&!it.field)out.push({...A,msg:`${nm}: la cornice per immagine è vuota.`});else if(!it.deco&&!it.alt.trim())out.push({...A,msg:`${nm}: manca il testo alternativo. Descrivi l’immagine, o segnala che è decorativa.`,fix:'alt'})}
   if(it.kind==='sign'){const M=pgSignMetrics(it,{row:isPg&&ii>=0?insts[ii].row:null});if(!M.lines.join('').trim()){out.push({...A,msg:`${nm}: l’insegna è vuota.`});continue}const bg=pgBehind(it,stack),big=M.size>=(mm?24:p.w/36)||(it.bold&&M.size>=(mm?18.66:p.w/48)),need=big?3:4.5,inks=pgSignInks(it);
    if(it.fillType==='image')out.push({...A,msg:`${nm}: le lettere mostrano un’immagine. Controlla a occhio che la scritta si legga, o aggiungi un contorno.`});
    else if(bg.color){const worst=inks.map(c=>pgContrast(c,bg.color)).filter(c=>c!=null).sort((a,b)=>a-b)[0];if(worst!=null&&worst<need)out.push({...A,msg:`${nm}: contrasto ${pgFmt(worst)}:1 tra la scritta e ${bg.by?'«'+bg.by.name+'»':'lo sfondo'}, ne serve almeno ${need}:1${it.glow>0?'. Il neon si legge su un fondo scuro':''}.`})}else if(bg.image)out.push({...A,msg:`${nm}: la scritta è sopra l’immagine «${bg.image.name}». Controlla a occhio che si legga.`});
    if(it.fillType==='none'&&M.size*it.ow/100<(mm?.4*MM:2))out.push({...A,msg:`${nm}: il contorno delle lettere vuote è molto sottile, difficile da leggere.`});if(M.size<small)out.push({...A,msg:`${nm}: scritta molto piccola (${pgFmt(pgToPt(M.size))} ${ptName()}).`});continue}
   if((it.kind==='rect'||it.kind==='ellipse'||it.kind==='tri')&&!it.deco&&!it.alt.trim())out.push({...A,msg:`${nm}: la forma non è decorativa ma non ha un testo alternativo.`,fix:'alt'});
   if(it.kind!=='text')continue;const s=p.stories[it.story];
   if(p.data)for(const f of storyText(s).matchAll(FIELD_RE)){const low=f[1].trim().toLowerCase();if(!PG_BUILTIN[low]&&!fields.has(low)){out.push({...A,msg:`${nm}: il campo «${f[1]}» non c’è nei dati${p.data?` (campi: ${p.data.fields.join(', ')})`:': scegli i dati dalla scheda Fonti'}.`});break}}
   const L=isPg&&ii>=0?lay.get(ii+'|'+it.id):null;if(L?.over&&!overSeen.has(it.story)){overSeen.add(it.story);out.push({...A,msg:`${nm}: il testo non entra, ${L.over} caratteri restano fuori. ${h.data&&s.chain.some(id=>!h.items.some(x=>x.id===id))?'Le pagine ripetute per ogni riga dei dati si impaginano da sole: il testo deve stare nelle cornici di questa pagina.':'Ingrandisci la cornice, riduci il testo o fallo continuare in una nuova cornice.'}`})}
   const styles=new Map();for(const ln of L?.lines||[])for(const pc of ln.pieces)styles.set(pc.st.color+'|'+pc.st.size+'|'+pc.st.bold,pc.st);if(!L)for(const pa of s.paras){const ps=p.ps[pa.ps]||p.ps.corpo;for(const r of pa.runs){const st=runSt(p,ps,r.cs);styles.set(st.color+'|'+st.size+'|'+st.bold,st)}}
   if(!styles.size)continue;const bg=pgBehind(it,stack);let worst=null;for(const st of styles.values()){const need=st.size>=big||(st.bold&&st.size>=bigBold)?3:4.5;if(bg.color){const c=pgContrast(st.color,bg.color);if(c!=null&&c<need&&(!worst||c/need<worst.c/worst.need))worst={c,need,st}}if(st.size<small){out.push({...A,msg:`${nm}: testo molto piccolo (${pgFmt(pgToPt(st.size))} ${ptName()}), difficile da leggere${mm?' stampato':' sui telefoni'}.`});break}}
   if(worst)out.push({...A,msg:`${nm}: contrasto ${pgFmt(worst.c)}:1 tra il testo e ${bg.by?'«'+bg.by.name+'»':'lo sfondo'}, ne serve almeno ${pgFmt(worst.need)}:1.`});
   else if(bg.image)out.push({...A,msg:`${nm}: il testo è sopra l’immagine «${bg.image.name}». Controlla a occhio che si legga, o mettici sotto una forma piena.`});
   else if(bg.partial)out.push({...A,msg:`${nm}: il testo è solo in parte sopra «${bg.partial.name}»: controlla il contrasto dove esce.`});
   if(it.opacity<100)out.push({...A,msg:`${nm}: la cornice è trasparente al ${it.opacity}%, il contrasto reale è più basso.`})}}
 return out}
async function pgCheck(){pgStorySync();const issues=pgIssues();await modal('Verifica dell’accessibilità',issues.length?`<p>${issues.length===1?'Un punto da controllare':issues.length+' punti da controllare'}:</p><ul class="issue-list">${issues.map((x,i)=>`<li><span>${esc(x.msg)}</span><span class="pg-btns">${x.fix==='order'?`<button type="button" class="btn sm" data-issue="${i}" data-fix="auto">Ordine automatico</button><button type="button" class="btn sm" data-issue="${i}" data-fix="ok">Va bene così</button>`:`<button type="button" class="btn sm" data-issue="${i}">Vai</button>`}</span></li>`).join('')}</ul>`:'<p class="ok-msg">Nessun problema trovato: immagini descritte, contrasto sufficiente, ordine di lettura coerente e tutto il testo dentro le cornici.</p>',[],'Chiudi',{noCancel:true,wide:true,
  onOpen:(pane,finish)=>pane.addEventListener('click',e=>{const b=e.target.closest('[data-issue]');if(!b)return;const x=issues[Number(b.dataset.issue)],fix=b.dataset.fix;finish(null);setTimeout(()=>{if(x.mid)pgGoPage(0,{mid:x.mid,say:false});else if(x.pi>=0)pgGoPage(x.pi,{say:false});
   if(fix==='auto'){runCommand('pgReadAuto');return}if(fix==='ok'){pgEdit('Ordine di lettura controllato',()=>{pgCurPage().readOk=true});announce('Ordine di lettura della pagina segnato come controllato');return}
   if(x.id){pgSelect(x.id);if(x.fix==='alt'){pgShowProps();$('pp-alt')?.focus()}else pgStage.focus()}else if(x.fix==='alt'){pgSelect(null,{say:false});pgShowProps();$('pp-alt')?.focus()}else pgStage.focus()},0)})})}
// Comandi sulle cornici.
function pgNeed(kind){const it=pgSel();if(!it||(kind&&it.kind!==kind)){toast(kind==='text'?'Scegli prima una cornice di testo':kind==='image'?'Scegli prima una cornice per immagine':'Scegli prima una cornice: nell’elenco delle cornici, sulla pagina con PgGiù, o con un clic');return null}return it}
function pgAdd(kind,o={},paras){const p=Pg.p,i=pgInner(p),w=o.w??(kind==='line'?i.w*.5:i.w*.6),h=o.h??(kind==='line'?0:kind==='text'?i.h*.22:i.h*.35),it=pgMk(p,kind,{x:i.x+(i.w-w)/2,y:i.y+(i.h-h)/2,w,h,...(kind==='text'?{cols:1}:{}),...o});
 Pg.sel=it.id;pgEdit('Inserisci '+it.name,q=>{if(kind==='text'){it.story=pgNewStory(q,paras||[P('corpo','')]);q.stories[it.story].chain.push(it.id)}pgPut(pgHolder(),it)},{props:true});return it}
const PG_ADD_SAY={sign:'Scrivi il testo nelle proprietà.',tri:'Le proprietà sono nel riquadro a destra.',text:'Scrivi nell’editor del testo; Esc torna alla pagina.',image:'Scegli il file dell’immagine.',rect:'Le proprietà sono nel riquadro a destra.',ellipse:'Le proprietà sono nel riquadro a destra.',line:'Le proprietà sono nel riquadro a destra.'};
function pgAddCmd(kind){const it=pgAdd(kind);announce(`Inserita la cornice «${it.name}» al centro della pagina, ultima nell’ordine di lettura. ${PG_ADD_SAY[kind]}`);if(kind==='text'){pgShowProps();setTimeout(()=>$('pgStory')?.focus(),0)};if(kind==='image')$('pgImgInput').click()}
function pgCloneItem(p,src,{dx=0,keepStory=false}={}){const it=JSON.parse(JSON.stringify(src));it.id=uid();it.x+=dx;it.y+=dx;let n=src.name.replace(/ copia( \d+)?$/,'')+' copia',k=2;const base=n,used=new Set(pgAllItems(p).map(x=>x.name));while(used.has(n))n=`${base} ${k++}`;it.name=n;
 if(it.kind==='text'&&!keepStory){const s=p.stories[src.story];it.story=pgNewStory(p,JSON.parse(JSON.stringify(s?.paras||[])));p.stories[it.story].chain.push(it.id)}return it}
function pgDup(){const it=pgNeed();if(!it)return;const d=pgMM()?5*MM:20;let c;pgEdit('Duplica '+it.name,p=>{c=pgCloneItem(p,it,{dx:d});const h=pgHolder();h.items.splice(h.items.indexOf(it)+1,0,c);h.read.push(c.id)},{props:true});Pg.sel=c.id;pgRenderAll({props:true});announce(`${c.name}, sopra l’originale e spostata di ${pgU(d)}${it.kind==='text'?', con una copia del testo':''}`)}
function pgRemove(p,h,it){h.items.splice(h.items.indexOf(it),1);h.read=h.read.filter(id=>id!==it.id);if(it.kind==='text'){const s=p.stories[it.story];if(s){s.chain=s.chain.filter(id=>id!==it.id);if(!s.chain.length)delete p.stories[it.story]}}}
function pgDelete(){const sel=pgSelItems();if(!sel.length){pgNeed();return}const items=pgMovable(sel,'eliminarla');if(!items.length)return;const it=items[0],h=pgHolder(),order=pgReadOrder(h),last=order.indexOf(items.at(-1)),next=order.slice(last+1).find(x=>!items.includes(x))||order.slice(0,order.indexOf(it)).reverse().find(x=>!items.includes(x)),chained=items.length===1&&it.kind==='text'&&Pg.p.stories[it.story]?.chain.length>1;Pg.sel=next?.id||null;
 pgEdit(items.length>1?`Elimina ${items.length} cornici`:'Elimina '+it.name,p=>{for(const x of items)pgRemove(p,h,x)},{props:true});announce(`${items.length>1?`Eliminate ${items.length} cornici`:`Eliminata la cornice «${it.name}»`}${chained?': il testo continua nelle altre cornici della catena':''}.${next?' Scelta: '+next.name:''}`)}
function pgCopy(cut){const it=pgNeed();if(!it)return;Pg.clip={it:JSON.parse(JSON.stringify(it)),paras:it.kind==='text'?JSON.parse(JSON.stringify(Pg.p.stories[it.story]?.paras||[])):null};if(cut)pgDelete();else toast(`Copiata la cornice «${it.name}»`)}
function pgPaste(){if(!Pg.clip){toast('Niente da incollare: copia prima una cornice');return}let c;pgEdit('Incolla',p=>{c=pgCloneItem(p,Pg.clip.it,{keepStory:true});if(c.kind==='text'){c.story=pgNewStory(p,JSON.parse(JSON.stringify(Pg.clip.paras||[])));p.stories[c.story].chain.push(c.id)}pgPut(pgHolder(),c)},{props:true});Pg.sel=c.id;pgRenderAll({props:true});announce(`Incollata la cornice «${c.name}», sopra le altre e ultima nell’ordine di lettura`)}
const PG_ORDER_SAY={front:'in primo piano, sopra tutte',back:'in fondo, sotto tutte',forward:'un livello più su',backward:'un livello più giù'};
function pgOrder(how){const it=pgNeed();if(!it)return;const items=pgHolder().items,i=items.indexOf(it),j=how==='front'?items.length-1:how==='back'?0:clampV(i+(how==='forward'?1:-1),0,items.length-1);if(i===j){toast(`La cornice «${it.name}» è già la più in ${how==='front'||how==='forward'?'alto':'basso'}`);return}
 pgEdit('Disponi '+it.name,()=>{items.splice(i,1);items.splice(j,0,it)});announce(`${it.name} ${PG_ORDER_SAY[how]}. L’ordine di lettura non cambia.`)}
const PG_ALIGN={L:['al margine sinistro',(it,i)=>[i.x-it.x,0]],C:['al centro tra i margini',(it,i)=>[i.x+(i.w-it.w)/2-it.x,0]],R:['al margine destro',(it,i)=>[i.x+i.w-it.w-it.x,0]],T:['al margine superiore',(it,i)=>[0,i.y-it.y]],M:['al centro, in verticale',(it,i)=>[0,i.y+(i.h-it.h)/2-it.y]],B:['al margine inferiore',(it,i)=>[0,i.y+i.h-it.h-it.y]]};
function pgAlign(k){const many=pgSelItems();if(many.length>1){pgAlignMulti(k,many);return}const it=pgNeed();if(!it)return;if(it.lock){toast(`«${it.name}» è bloccata`);return}const [say,fn]=PG_ALIGN[k],[dx,dy]=fn(it,pgInner(Pg.p));if(pgEdit('Allinea '+it.name,()=>{it.x+=dx;it.y+=dy}))announce(`La cornice «${it.name}» è allineata ${say}`);else toast(`La cornice «${it.name}» è già allineata ${say}`)}
function pgReadMove(dir){const it=pgNeed();if(!it)return;const h=pgHolder(),order=pgReadOrder(h).map(x=>x.id),i=order.indexOf(it.id),j=i+dir;if(j<0||j>=order.length){toast(`«${it.name}» è già ${dir<0?'la prima':'l’ultima'} nell’ordine di lettura`);return}
 order.splice(i,1);order.splice(j,0,it.id);pgEdit('Ordine di lettura',()=>{h.read=order;if(!Pg.mid)h.readOk=true});announce(`${it.name}: ${j+1} di ${order.length} nell’ordine di lettura`)}
function pgReadAuto(){const h=pgHolder(),ids=pgAutoOrder(h).map(x=>x.id);if(!pgEdit('Ordine di lettura automatico',()=>{h.read=ids;if(!Pg.mid)h.readOk=false})){toast('L’ordine di lettura segue già la disposizione');return}announce('Ordine di lettura dalla disposizione: '+pgReadOrder(h).filter(x=>!x.deco).map(x=>x.name).join(', '))}
// Catene del testo: una cornice nuova che continua il testo, il collegamento a una cornice esistente, lo scollegamento.
function pgLink(){const it=pgNeed('text');if(!it)return;if(Pg.mid){toast('Nei mastri ogni cornice ha il suo testo');return}const p=Pg.p,h=pgHolder(),i=pgInner(p);let target=h,nw=null;
 if(it.h<i.h*.5&&it.y+it.h*2+(pgMM()?4*MM:16)<=i.y+i.h+1)nw={x:it.x,y:it.y+it.h+(pgMM()?4*MM:16),w:it.w,h:it.h};
 pgEdit('Continua il testo',q=>{if(!nw){q.pages.splice(Pg.pi+1,0,{...pgBlankPage(q),master:h.master,data:h.data});target=q.pages[Pg.pi+1];nw={x:i.x,y:i.y,w:i.w,h:i.h}}
  const c=pgMk(q,'text',{...nw,cols:it.cols,gut:it.gut,pad:it.pad,fill:it.fill,story:it.story});pgPut(target,c);const ch=q.stories[it.story].chain;ch.splice(ch.indexOf(it.id)+1,0,c.id);Pg.lastLinked=c.id},{props:true});
 const c=pgWhere(Pg.lastLinked);announce(`Il testo continua nella cornice «${c.it.name}»${c.holder===h?' sotto questa':`, a pagina ${c.pi+1}`}${pgFrameLay(it)?.over?'':'. Ora tutto il testo entra'}`);pgRenderAll({props:true})}
function pgLinkToMenu(){const it=pgNeed('text');if(!it)return;const p=Pg.p,ch=p.stories[it.story].chain,cands=[];p.pages.forEach((pg,i)=>{for(const x of pg.items)if(x.kind==='text'&&!ch.includes(x.id)&&pg.data===(pgCurPage()?.data||false))cands.push({x,label:`${x.name}, pagina ${i+1}`})});
 if(Pg.mid||!cands.length){toast(Pg.mid?'Nei mastri ogni cornice ha il suo testo':'Non ci sono altre cornici di testo da collegare: usa «Continua in nuova cornice»');return}const a=document.querySelector('#ribbon [data-action="pgLinkTo"]')?.getBoundingClientRect()||pgStage.getBoundingClientRect();
 openMenu(cands.map(({x,label})=>({label,desc:storyText(p.stories[x.story]).trim()?'Il suo testo si aggiunge in fondo a questo':'Vuota',run:()=>pgLinkTo(it,x)})),a.left,a.bottom,'Collega il testo a una cornice',document.querySelector('#ribbon [data-action="pgLinkTo"]'))}
function pgLinkTo(it,x){pgEdit('Collega il testo',p=>{const s=p.stories[it.story],old=p.stories[x.story],oldCh=old.chain.filter(id=>id!==x.id);if(storyText(old).trim())s.paras.push(...old.paras);if(oldCh.length){old.chain=oldCh}else delete p.stories[x.story];x.story=it.story;s.chain.splice(s.chain.indexOf(it.id)+1,0,x.id)},{props:true});announce(`Il testo di «${it.name}» continua in «${x.name}»`)}
function pgUnlink(){const it=pgNeed('text');if(!it)return;const s=Pg.p.stories[it.story];if(s.chain.length<2){toast(`La cornice «${it.name}» non è collegata ad altre`);return}pgEdit('Scollega '+it.name,p=>{p.stories[it.story].chain=s.chain.filter(id=>id!==it.id);it.story=pgNewStory(p,[P('corpo','')]);p.stories[it.story].chain.push(it.id)},{props:true});announce(`«${it.name}» è fuori dalla catena e ora è vuota: il testo continua nelle altre cornici`)}
function pgOverflow(){const p=Pg.p,insts=pgViewInstances(p),lay=pgLayout(p,insts);for(const [k,v] of lay)if(v.over){const ii=+k.split('|')[0],I=insts[ii],it=v.it;if(I.pg.items.includes(it)){pgGoPage(I.i,{say:false});pgSelect(it.id,{say:false})}else{const m=pgMasterOf(I.pg);pgGoPage(0,{mid:m.id,say:false});pgSelect(it.id,{say:false})}announce(`«${it.name}»: il testo non entra, ${v.over} caratteri restano fuori. Ingrandisci la cornice con Ctrl+frecce o usa «Continua in nuova cornice».`);pgStage.focus();return}toast('Tutto il testo entra nelle cornici')}
// Pagine e mastri.
function pgAddPage(){const pg=pgCurPage()||Pg.p.pages.at(-1);pgEdit('Nuova pagina',p=>{p.pages.splice(Pg.pi+1,0,{...pgBlankPage(p),master:pg.master})});pgGoPage(Pg.pi+1,{say:false});announce(`Nuova pagina ${Pg.pi+1} di ${Pg.p.pages.length}${pgMasterOf(pgCurPage())?', con '+pgMasterOf(pgCurPage()).name:''}`)}
function pgDupPage(){const pg=pgCurPage();if(!pg)return;pgEdit('Duplica la pagina',p=>{const ids=new Map(),done=new Map(),copy={...JSON.parse(JSON.stringify(pg)),id:uid(),items:[],read:[]};
 for(const it of pg.items){const c=pgCloneItem(p,it,{keepStory:true});ids.set(it.id,c.id);copy.items.push(c)}
 // Una catena tutta dentro la pagina si copia con le sue cornici; una che continua altrove diventa un testo a sé.
 for(const c of copy.items)if(c.kind==='text'){const s=p.stories[c.story],inside=s.chain.every(id=>ids.has(id));if(inside&&done.has(c.story)){c.story=done.get(c.story);continue}const ns=pgNewStory(p,JSON.parse(JSON.stringify(s.paras)));p.stories[ns].chain=inside?s.chain.map(id=>ids.get(id)):[c.id];if(inside)done.set(c.story,ns);c.story=ns}
 copy.read=pg.read.map(id=>ids.get(id)).filter(Boolean);p.pages.splice(Pg.pi+1,0,copy)});pgGoPage(Pg.pi+1,{say:false});announce(`Pagina duplicata: ora sei sulla pagina ${Pg.pi+1}, la copia`)}
async function pgDelPage(){const p=Pg.p,pg=pgCurPage();if(!pg)return;if(p.pages.length===1){toast('Il documento ha una sola pagina: non si può eliminare');return}if(pg.items.length&&!(await confirmAction(`Eliminare la pagina ${Pg.pi+1} con le sue ${pg.items.length} cornici? Puoi annullare con Ctrl+Z.`)))return;
 pgEdit('Elimina la pagina',q=>{for(const it of [...pg.items])pgRemove(q,pg,it);q.pages.splice(Pg.pi,1)});pgGoPage(Math.min(Pg.pi,p.pages.length-1),{say:false});announce(`Pagina eliminata: ora sei sulla pagina ${Pg.pi+1} di ${Pg.p.pages.length}`)}
function pgMovePage(dir){const p=Pg.p,i=Pg.pi,j=i+dir;if(Pg.mid||j<0||j>=p.pages.length){toast('La pagina è già la '+(dir<0?'prima':'ultima'));return}pgEdit('Sposta la pagina',q=>{const [pg]=q.pages.splice(i,1);q.pages.splice(j,0,pg)});Pg.pi=j;pgRenderAll();announce(`Pagina spostata: ora è la ${j+1} di ${p.pages.length}`)}
function pgStepPage(dir){const p=Pg.p;if(Pg.mid){pgGoPage(Pg.pi);return}const j=Pg.pi+dir;if(j<0||j>=p.pages.length){toast(dir<0?'Sei sulla prima pagina':'Sei sull’ultima pagina');return}pgGoPage(j)}
function pgStepRow(dir){const p=Pg.p,n=p.data?.rows.length||0;if(!n){toast('Non ci sono dati: sceglili dalla scheda Fonti');return}Pg.row=clampV(Pg.row+dir,0,n-1);pgRenderAll({props:true});pgPersistSoon();announce(`Anteprima della riga ${Pg.row+1} di ${n}: ${p.data.rows[Pg.row].filter(v=>v.trim()).slice(0,3).join(', ')}`)}
function pgDataRepeat(){const pg=pgCurPage();if(!pg){toast('Scegli una pagina, non un mastro');return}pgEdit('Ripeti per ogni riga',()=>{pg.data=!pg.data},{props:true});const out=pg.items.some(it=>it.kind==='text'&&Pg.p.stories[it.story]?.chain.some(id=>!pg.items.some(x=>x.id===id)));
 announce(pg.data?(Pg.p.data?`La pagina ${Pg.pi+1} si ripete per ognuna delle ${plural(Pg.p.data.rows.length,'riga','righe')} dei dati`:'Ora scegli i dati dalla scheda Fonti')+(out?'. Attenzione: un testo di questa pagina continua su un’altra; nelle pagine ripetute ogni copia si impagina da sola.':''):`La pagina ${Pg.pi+1} torna a una copia sola`)}
function pgMasterMenu(){const pg=pgCurPage();if(!pg){toast('Scegli prima una pagina');return}const a=document.querySelector('#ribbon [data-action="pgMasterApply"]'),r=(a||pgStage).getBoundingClientRect();
 openMenu([{label:'Nessun mastro',checked:!pg.master,run:()=>pgSetMaster(pg,'')},...Pg.p.masters.map(m=>({label:m.name,checked:pg.master===m.id,run:()=>pgSetMaster(pg,m.id)})),'-',{label:'Applica il mastro di questa pagina a tutte',icon:'header',run:()=>{pgEdit('Mastro a tutte le pagine',p=>{for(const x of p.pages)x.master=pg.master});announce('Mastro applicato a tutte le pagine')}}],r.left,r.bottom,'Mastro della pagina',a)}
function pgSetMaster(pg,id){pgEdit('Mastro della pagina',()=>{pg.master=id},{props:true});announce(id?`La pagina ${Pg.pi+1} usa ${pgMasterOf(pg).name}`:`La pagina ${Pg.pi+1} non usa più un mastro`)}
function pgMasterEdit(){const p=Pg.p,id=pgCurPage()?.master||p.masters[0]?.id;if(!id){pgMasterNew();return}pgGoPage(0,{mid:id});pgStage.focus()}
function pgMasterNew(){const p=Pg.p,letter=String.fromCharCode(65+p.masters.length%26),m={id:uid(),name:'Mastro '+letter,items:[],read:[]};pgEdit('Nuovo mastro',q=>{q.masters.push(m)});pgGoPage(0,{mid:m.id,say:false});announce(`Nuovo ${m.name}, vuoto. Inserisci il numero di pagina, l’intestazione o il logo, poi applicalo alle pagine.`)}
async function pgDelMaster(){const p=Pg.p,m=pgHolder(),used=p.pages.filter(x=>x.master===m.id).length;if(used&&!(await confirmAction(`${m.name} è usato da ${used} pagine: eliminarlo? Le pagine resteranno senza mastro.`)))return;pgEdit('Elimina il mastro',q=>{for(const it of [...m.items])pgRemove(q,m,it);q.masters=q.masters.filter(x=>x!==m);for(const x of q.pages)if(x.master===m.id)x.master=''});pgGoPage(Pg.pi)}
// Elementi ripetuti: si aggiungono al mastro della pagina (o a uno nuovo) e si apre il mastro per vederli.
function pgMasterAdd(what){const p=Pg.p;let m=Pg.mid?pgHolder():pgMasterOf(pgCurPage());if(!m){const pg=pgCurPage();m={id:uid(),name:'Mastro '+String.fromCharCode(65+p.masters.length%26),items:[],read:[]};pgEdit('Nuovo mastro',q=>{q.masters.push(m);pg.master=m.id})}
 const i=pgInner(p),b=p.ps.note.size*1.7,band=(y,hh)=>({x:i.x,y,w:i.w,h:Math.max(b,hh)});let it;Pg.mid=m.id;
 if(what==='num')it=pgAdd('text',{name:'Numero di pagina',...band(i.y+i.h+Math.max(4,(p.m.b-b)/2),b)},[P('numero','«Pagina» / «Pagine»')]);
 else if(what==='head')it=pgAdd('text',{name:'Intestazione',...band(Math.max(4,(p.m.t-b)/2),b)},[P('note','«Titolo del documento»')]);
 else{const s=Math.max(24,p.m.t*.6);it=pgAdd('image',{name:'Logo',x:i.x+i.w-s*2,y:(p.m.t-s)/2,w:s*2,h:s,fit:'fit',fx:100})}
 pgGoPage(0,{mid:m.id,say:false});pgSelect(it.id,{say:false});announce(`Aggiunto al ${m.name} «${it.name}»: compare su ${p.pages.filter(x=>x.master===m.id).length} pagine. Stai modificando il mastro: torna alle pagine dall’elenco delle pagine.`);if(what==='logo')$('pgImgInput').click();else pgStage.focus()}
// Campi nel testo: «Pagina», «Pagine», il titolo, la data e i campi dei dati, inseriti al cursore dell'editor.
